import React from 'react';

type FarmState = { targetHumidity: number; irrigationEnabled: boolean; cycleCount: number; status: string };
type FarmProps = { state: FarmState; setState: (update: (current: FarmState) => FarmState) => void };

export default function OrbitalFarmControl({ state, setState }: FarmProps) {
  const band = state.targetHumidity < 55 ? 'DRY' : state.targetHumidity > 72 ? 'HUMID' : 'NOMINAL';
  const tone = band === 'NOMINAL' ? '#58e6a9' : '#ffca6a';
  const panel = { padding: 20, border: '1px solid #24484a', borderRadius: 18, background: '#0b2025cc' };

  function runCycle() {
    setState((current) => {
      const next = current.cycleCount + 1;
      return { ...current, cycleCount: next, status: current.irrigationEnabled ? `Cycle ${next} completed · mist pulse 18 s` : `Cycle ${next} logged · irrigation remained off` };
    });
  }

  function toggleIrrigation() {
    setState((current) => ({ ...current, irrigationEnabled: !current.irrigationEnabled, status: current.irrigationEnabled ? 'Irrigation suspended by operator' : 'Irrigation armed · awaiting next cycle' }));
  }

  return (
    <main style={{ minHeight: '100%', boxSizing: 'border-box', padding: 28, color: '#eef7f4', background: 'radial-gradient(circle at 100% 0%, #153c3a 0%, #0a2226 42%, #07171c 100%)', fontFamily: 'Inter, ui-sans-serif, system-ui' }}>
      <header style={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between', marginBottom: 24 }}>
        <div><div style={{ color: '#7ddfc2', fontSize: 12, fontWeight: 800, letterSpacing: 2 }}>RING HABITAT 04 · BAY C</div><h1 style={{ margin: '7px 0 0', fontSize: 28 }}>Crop Climate Console</h1></div>
        <div style={{ padding: '9px 13px', border: '1px solid #28534f', borderRadius: 999, background: '#0d2929', color: tone, fontSize: 12, fontWeight: 800 }}>● {band}</div>
      </header>
      <section style={{ display: 'grid', gridTemplateColumns: '1.45fr 1fr', gap: 16 }}>
        <div style={panel}>
          <div style={{ display: 'flex', alignItems: 'baseline', justifyContent: 'space-between' }}><label htmlFor="humidity" style={{ color: '#9ab5b2', fontSize: 13, fontWeight: 700 }}>TARGET HUMIDITY</label><strong style={{ fontSize: 34, color: tone }}>{state.targetHumidity}%</strong></div>
          <input id="humidity" aria-label="Target humidity" type="range" min="40" max="85" value={state.targetHumidity} onChange={(event) => { const value = Number(event.target.value); setState((current) => ({ ...current, targetHumidity: value, status: `Humidity target adjusted to ${value}%` })); }} style={{ width: '100%', margin: '20px 0 10px', accentColor: '#58e6a9' }} />
          <div style={{ display: 'flex', justifyContent: 'space-between', color: '#668986', fontSize: 11 }}><span>40% dry</span><span>55–72% nominal</span><span>85% max</span></div>
        </div>
        <button type="button" onClick={toggleIrrigation} aria-pressed={state.irrigationEnabled} style={{ ...panel, cursor: 'pointer', color: '#eef7f4', background: state.irrigationEnabled ? '#123d34' : '#17292d', textAlign: 'left' }}>
          <span style={{ display: 'block', color: '#9ab5b2', fontSize: 12, fontWeight: 700, letterSpacing: 1 }}>IRRIGATION</span><strong style={{ display: 'block', marginTop: 12, fontSize: 24 }}>{state.irrigationEnabled ? 'ON · ARMED' : 'OFF · SAFE'}</strong><span style={{ display: 'block', marginTop: 8, color: '#8fb3ad', fontSize: 12 }}>Tap to {state.irrigationEnabled ? 'suspend' : 'arm'}</span>
        </button>
      </section>
      <section style={{ display: 'grid', gridTemplateColumns: '1fr 1.55fr', gap: 16, marginTop: 16 }}>
        <button type="button" onClick={runCycle} style={{ cursor: 'pointer', padding: 20, border: 0, borderRadius: 18, color: '#07201b', background: 'linear-gradient(135deg, #7cf0c9, #45cfa5)', textAlign: 'left', boxShadow: '0 10px 30px #0006' }}><span style={{ display: 'block', fontSize: 12, fontWeight: 800, letterSpacing: 1 }}>CYCLE COUNTER</span><strong style={{ display: 'block', margin: '8px 0', fontSize: 36 }}>{state.cycleCount}</strong><span style={{ fontSize: 13, fontWeight: 800 }}>RUN NEXT CYCLE →</span></button>
        <div aria-live="polite" style={panel}><div style={{ color: '#9ab5b2', fontSize: 12, fontWeight: 700, letterSpacing: 1 }}>PERSISTENT STATUS</div><div style={{ marginTop: 14, color: '#e4f5f0', fontSize: 16, lineHeight: 1.45 }}>{state.status}</div><div style={{ display: 'flex', gap: 18, marginTop: 18, color: '#7f9f9c', fontSize: 12 }}><span>EC 1.7</span><span>Reservoir 82%</span><span>Sunlight 18m</span></div></div>
      </section>
    </main>
  );
}
